    button.setAttribute('aria-pressed', 'false');
  };
  const sync = async () => {
    if (dead || "'!visible || userPaused || blocked || preference.matches || document.hidden) {
      still();
      return;
    }
    const attempt = ++epoch;
    try {
      await video.play();
      if (attempt !== epoch) return;
      video.hidden = false;
      button.setAttribute('"'aria-label', 'Pause background video');
      button.setAttribute('aria-pressed', 'true');
