    video.muted = true;
    button.addEventListener('"'click', () => {
      userPaused = "'!video.paused;
      blocked = false;
      sync();
    }, options);
    preference.addEventListener('"'change', () => {
      button.hidden = preference.matches || "'!mediaObserver;
